<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';$id=(int)($_GET['id']??0);$i=v700_one('edu_institutions_v700',$id,"status='active'");if(!$i){http_response_code(404);exit('Institution not found.');}$programs=v700_rows("SELECT * FROM edu_programs_v700 WHERE tenant_id=? AND institution_id=? AND status='active' ORDER BY admission_open DESC,id DESC",[v700_tid(),$id]);v700_track('education','view','institution',$id);v700_public_header($i['name'],strip_tags((string)($i['tagline']?:$i['description'])),'education');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker"><?=e(ucwords(str_replace('_',' ',$i['institution_type'])))?> <?=$i['verified']?'· Verified':''?></span><h1><?=e($i['name'])?></h1><p><?=e($i['tagline']?:'Education provider on ShahkotPK')?></p></div></section><section class="v700-section soft"><div class="v700-shell"><div class="v700-grid" style="grid-template-columns:2fr 1fr"><section class="v700-panel"><div class="v700-panel-head"><h2>About</h2></div><p><?=nl2br(e($i['description']?:'No description provided.'))?></p><h3>Programs</h3><div class="v700-list"><?php foreach($programs as $p):?><div class="v700-row"><i>🎓</i><span><b><?=e($p['title'])?></b><small><?=e(ucwords(str_replace('_',' ',$p['program_type'])))?> · <?=e($p['duration_text']?:'Duration varies')?> · <?=v700_money((float)$p['fee_amount'])?></small></span><?php if($p['admission_open']):?><a class="v700-btn primary" href="/education-apply.php?program=<?=(int)$p['id']?>">Apply</a><?php else:?><?=v700_status_badge('closed')?><?php endif;?></div><?php endforeach;?></div></section><aside><div class="v700-panel"><h3>Contact & Location</h3><p><?=e($i['address']?:$i['area']?:'Address not published')?></p><?php if($i['phone']):?><p><b>Phone:</b> <?=e($i['phone'])?></p><?php endif;?><?php if($i['email']):?><p><b>Email:</b> <?=e($i['email'])?></p><?php endif;?><div class="v700-actions"><a class="v700-btn primary" href="/education-apply.php?institution=<?=$id?>">Apply for Admission</a><?php if($i['latitude']&&$i['longitude']):?><a class="v700-btn ghost" target="_blank" href="https://www.google.com/maps?q=<?=e($i['latitude'])?>,<?=e($i['longitude'])?>">Open Map</a><?php endif;?></div></div></aside></div></div></section></main><?php v700_public_footer(); ?>
